# Sum-of-Exponentials (SOE) decomposition of the soft-Coulomb kernel
# 1/√(1+t²) ≈ Σ_{k=1}^{35} w_k exp(-s_k t)
# Valid on t ∈ [0, 40], max abs error = 1.71e-07, mean abs error = 2.71e-09
# 35 real terms, all decaying (s_k > 0), max |w_k| = 42.35
# Generated by conditioned VARPRO fit with weight regularization

const N_SOE = 35

const SOE_S = [
