"""
    soft_coulomb_soe(r)

Evaluate the SOE approximation: Σ w_k exp(-s_k |r|)
"""
function soft_coulomb_soe(r)
    v = 0.0
    t = abs(r)
    for k in 1:N_SOE
        v += SOE_W[k] * exp(-SOE_S[k] * t)
    end
    return v
end
